    42	static void test_all_from(const char *dirname)
    43	{
    44	        DIR *dirp;
    45	        struct dirent *dp;
    46	        char fname[1024];
    47	        int len;
    48	
    49	        if ((dirp = opendir(dirname))) {
    50	                while ((dp = readdir(dirp))) {
    51	                        if (*dp->d_name == '.') continue;
    52	
    53	                        len = snprintf(fname, sizeof(fname), "%s/%s", dirname, dp->d_name);
    54	                        if (len < 0 || len >= (int) sizeof(fname)) {
    55	                                fprintf(stderr, "File name truncation: %s/%s\n", dirname, dp->d_name);
    56	                                continue;
    57	                        }
    58	
    59	                        int fd;
    60	                        if ((fd = open(fname, O_RDONLY)) == -1) {
    61	                                fprintf(stderr, "Failed to open %s (%d)\n", fname, errno);
    62	                                continue;
    63	                        }
    64	
    65	                        struct stat st;
    66	                        if (fstat(fd, &st) != 0) {
    67	                                fprintf(stderr, "Failed to stat %d (%d)\n", fd, errno);
    68	                                close(fd);
    69	                                continue;
    70	                        }
    71	
    72	                        uint8_t *data = malloc(st.st_size);
    73	                        ssize_t n;
    74	                        if ((n = read(fd, data, st.st_size)) == st.st_size) {
    75	                                printf("testing %llu bytes from '%s'\n", (unsigned long long) st.st_size, fname);
    76	                                LLVMFuzzerTestOneInput(data, st.st_size);
    77	                        } else
    78	                                fprintf(stderr, "Failed to read %llu bytes from %s (%d), got %d\n", (unsigned long long) st.st_size, fname, errno, (int) n);
    79	
    80	                        free(data);
    81	                        close(fd);
    82	                }
    83	                closedir(dirp);
    84	        }
    85	}
